def variants(s):
    b=s.encode()
    return [b, b.hex().encode(), b.hex().upper().encode(), s.encode('utf-16-be'), s.encode('utf-16-le')]
hits=[]
def scan(label,data):
    for n in needles:
        for v in variants(n):
            if v in data: hits.append((label,n))
    # nested zip
    if data[:2]==b'PK':
        z=zipfile.ZipFile(io.BytesIO(data))
        for i in z.infolist(): scan(label+'!'+i.filename, z.read(i))
        if z.comment: scan(label+'!comment', z.comment)
raw=open(path,'rb').read()
scan('raw',raw)
# brute force: inflate any zlib blob in raw
for m in re.finditer(rb'stream\r?\n',raw):
