        scan('obj%s'%(o.objgen,),o.read_bytes())
    scan('objrepr%s'%(getattr(o,'objgen',None),),repr(o).encode('utf8','replace'))
scan('trailer',repr(p.trailer).encode())
print('raw %%EOF count',raw.count(b'%%EOF'),'objects',len(p.objects))
print('HITS:',sorted(set(hits)) or 'none')
